  _ = `ตลอดระยะเวลา 15 ปีที่ผ่านมา Gautam ได้ปฏิบัติงานด้านแฟรนไชส์และผลิตภัณฑ์จำนวนมากของ Valve โดยรวมถึง Left 4 Dead, Portal, Half-Life, Counter-Strike, Alien Swarm และ Steam ขณะนี้เขามีส่วนร่วมใน CS: GO`,
