  _ = `สถานะ:  ยังไม่ได้เริ่มขั้นตอนช่วยเหลือ`,
  _ = `สถานะ:  ไม่มีการรองรับคอนโทรลเลอร์`,
  _ = `เริ่มขั้นตอนช่วยเหลือ`,
