  _ = `บันทึกและออก`,
  _ = `ขั้นตอนที่ %1$s`,
  _ = `เริ่มขั้นตอนช่วยเหลือ`,
  _ = `มีการอัปเดตคุณสมบัติการช่วยการเข้าถึงหลังจากที่คุณได้ดำเนินการตามขั้นตอนช่วยเหลือเสร็จสิ้นแล้ว`,
  _ = `ดูหน้าที่ได้รับการอัปเดต`,
  _ = `ใช้ปุ่มนี้เพื่อไปยังหน้าขั้นตอนช่วยเหลือที่ได้รับการอัปเดตเท่านั้น`,
  _ = `โปรดตอบคำถามเกี่ยวกับคุณสมบัติการช่วยการเข้าถึงในเกมของคุณ เพื่อช่วยให้ผู้เล่นสามารถหาเกมที่ตรงกับความต้องการในการช่วยการเข้าถึงของตนได้`,
  _ = `เมื่อพิจารณาจากสิ่งที่คุณบอกเราเกี่ยวกับคุณสมบัติการช่วยการเข้าถึงของคุณ Steam จะแสดงให้ลูกค้าเห็นรายการที่ขยายได้ดังต่อไปนี้:`,
  _ = `ข้อมูลที่คุณแจ้งให้เราทราบแสดงว่า เกมของคุณไม่มีคุณสมบัติการช่วยการเข้าถึงที่ Steam รองรับ`,
