  _ = `เกมเพลย์`,
  _ = `หากต้องการรายละเอียดเกี่ยวกับคุณสมบัติการช่วยการเข้าถึงเกมเพลย์ โปรดอ่าน<1>เอกสาร Steamworks เกี่ยวกับคุณสมบัติการช่วยการเข้าถึง</1>`,
  _ = `เกมของคุณรองรับคุณสมบัติการช่วยการเข้าถึงเกมเพลย์ข้อใดเหล่านี้?`,
  _ = `ปรับระดับความยากได้`,
  _ = `การตั้งค่าความยากช่วยให้ผู้เล่นสามารถปรับให้ประสบการณ์การเล่นเกมของตนสอดคล้องกับความสามารถและความชอบของตนได้`,
  _ = `บันทึกได้ทุกเวลา`,
  _ = `ผู้เล่นสามารถบันทึกเกมเพลย์โดยใช้ได้ทั้งการบันทึกอัตโนมัติและบันทึกด้วยตนเอง และสามารถบันทึกได้ทุกเวลาในเกม ผู้เล่นสามารถมองหาแท็กนี้ได้เพื่อให้ทราบว่าตนจะไม่สูญเสียความคืบหน้าที่สำคัญไป`,
