  _ = `ผู้เล่นที่มีความบกพร่องทางสายตาอาจอาศัยเสียงบรรยายในการใช้งานเมนู หากเกมของคุณมีเมนูเกมแบบมีเสียงบรรยาย หมายความว่าคุณได้แสดงแผนภูมิ UI ให้โปรแกรมอ่านหน้าจอ (เช่น ผ่านทาง <1>Microsoft UI Automation</1>) หรือจัดให้เมนูเกมและการแจ้งเตือนทั้งหมดมีเสียงบรรยาย หากคุณต้องการคำแนะนำในเรื่องนี้ โปรดอ่าน<2>เอกสาร Steamworks เกี่ยวกับคุณสมบัติการช่วยการเข้าถึง</2>`,
  _ = `เกมของคุณมีเมนูเกมแบบมีเสียงบรรยายใช่หรือไม่?`,
