  _ = `ไม่ เกมของฉันไม่มีเมนูเกมแบบมีเสียงบรรยาย`,
  _ = `เล่นได้โดยไม่ต้องมอง`,
  _ = `ผู้เล่นสามารถเล่นเกมได้อย่างเต็มรูปแบบโดยไม่จำเป็นต้องมองหน้าจอเลย ไม่ว่าจะเป็นเพราะเกมของคุณได้รับการออกแบบมาให้เกมเพลย์ไม่ต้องใช้การมองเห็น (เช่น ใช้เสียง) หรือมีการรองรับโปรแกรมอ่านหน้าจอ หรือเสียงบรรยายนั้นสมบูรณ์เพียงพอที่ผู้เล่นจะสามารถสัมผัสประสบการณ์การเล่นทั้งเกมได้`,
  _ = `บางเกมสามารถเล่นได้โดยไม่ต้องมองหน้าจอ ตัวอย่างเช่น เกมอาจออกแบบมาโดยใช้เสียงเป็นหลัก หรืออาจรองรับโปรแกรมอ่านหน้าจอหรือมีเสียงบรรยายที่เพียงพอในการมอบประสบการณ์การเล่นเกมที่สมบูรณ์โดยไม่ต้องใช้การมองเห็น`,
