  _ = `ผู้เล่นอาจจำเป็นต้องลดระดับเสียงที่รบกวนสมาธิ เพื่อให้สามารถจดจ่อกับเสียงที่ตนต้องการได้ยิน หากเกมของคุณมีการควบคุมระดับเสียงแบบกำหนดเอง ผู้เล่นจะสามารถปรับระดับเสียงสัมพัทธ์ของเสียงประเภทต่าง ๆ ได้ เช่น ดนตรี เอฟเฟกต์เสียง เสียงจากสิ่งแวดล้อม และเสียงพูดของตัวละคร หากมีแถบเลื่อนปรับระดับเสียงเพียงแถบเดียวจะถือว่าไม่ตรงตามเกณฑ์นี้ หากต้องการคำแนะนำ โปรดอ่าน<1>เอกสาร Steamworks เกี่ยวกับคุณสมบัติการช่วยการเข้าถึง</1>`,
  _ = `เกมของคุณมีการควบคุมระดับเสียงแบบกำหนดเองใช่หรือไม่?`,
