  _ = `ผู้เล่นอาจต้องอาศัยสัญญาณเสียงเพื่อทำความเข้าใจกับตำแหน่งของวัตถุในเกม หากเกมของคุณมีระบบเสียงสเตอริโอ ระบบจะถ่ายทอดตำแหน่งสัมพัทธ์ของเสียงโดยอาศัยช่องสัญญาณซ้ายและขวา หากเกมของคุณมีระบบเสียงรอบทิศทาง ผู้เล่นจะสามารถบอกได้ว่าเสียงมาจากทิศทางใดในทุกทิศทาง รวมทั้งด้านบน ด้านล่าง ด้านหลัง และด้านหน้า`,
  _ = `เกมคุณรองรับระบบเสียงแบบแยกทิศทางในข้อใดเหล่านี้?`,
