  _ = `อินพุต`,
  _ = `ผู้เล่นบางคนมีเครื่องมือการช่วยการเข้าถึงที่เชื่อมโยงกับคีย์บอร์ด เมาส์ หรืออินพุตแบบสัมผัส หรือผู้เล่นอาจชอบใช้อินพุตเหล่านั้น หากต้องการรายละเอียดเกี่ยวกับคุณสมบัติการช่วยการเข้าถึงอินพุต โปรดอ่าน<1>เอกสาร Steamworks เกี่ยวกับคุณสมบัติการช่วยการเข้าถึง</1>`,
