  _ = `การแปลงข้อความเป็นเสียงพูดในแช็ตและการแปลงเสียงพูดเป็นข้อความในแช็ต`,
  _ = `ประสบการณ์ทางสังคม เช่น การแช็ตด้วยข้อความและการแช็ตด้วยเสียงในเกมอาจไม่พร้อมให้ผู้เล่นที่มีความบกพร่องทางสายตาหรือการได้ยินใช้งานได้ การแปลงข้อความเป็นเสียงพูดในแช็ตจะช่วยให้ผู้เล่นได้ยินเสียงตามข้อความแช็ตในลักษณะเรียลไทม์ ส่วนการแปลงเสียงพูดเป็นข้อความในแช็ตจะช่วยให้ผู้เล่นสามารถอ่านข้อความตามการแช็ตด้วยเสียงในลักษณะเรียลไทม์ได้เช่นกัน หากต้องการคำแนะนำเกี่ยวกับคุณสมบัติการแปลงข้อความเป็นเสียงพูดในแช็ตและการแปลงเสียงพูดเป็นข้อความในแช็ต โปรดอ่าน<1>เอกสาร Steamworks เกี่ยวกับคุณสมบัติการช่วยการเข้าถึง</1>`,
