  _ = `การทำเช่นนี้จะคัดลอกการตั้งค่าทั้งหมดของโครงการที่เผยแพร่แล้วตามที่เลือกไว้ไปยังโครงการที่ยังไม่ได้เผยแพร่นี้ คุณแน่ใจหรือไม่?`,
