  _ = `การรองรับอินพุตทั่วไป`,
  _ = `เรามีขั้นตอนช่วยเหลืออย่างรวดเร็วที่ประกอบด้วยคำถามสั้น ๆ สองสามข้อ เพื่ออธิบายให้ผู้เล่นเข้าใจได้มากที่สุดว่าเกมของคุณรองรับคอนโทรลเลอร์ในระดับใด โปรดตอบคำถามในขั้นตอนช่วยเหลือนี้ให้ละเอียดที่สุดเท่าที่จะทำได้ เพื่อให้ Steam สามารถแนะนำเกมที่เล่นได้ดีกับอุปกรณ์ที่ผู้เล่นมีอยู่`,
