  _ = `ไม่ เกมของฉันไม่ได้ใช้ Steam Input API`,
  _ = `การรองรับคอนโทรลเลอร์ Xbox`,
  _ = `หากเกมของคุณรองรับคอนโทรลเลอร์ Xbox อย่างเต็มรูปแบบ ผู้เล่นจะสามารถเปิด กำหนดค่า เล่น และออกจากเกมได้โดยไม่ต้องใช้คีย์บอร์ด โดยจะถือว่าเกมของคุณรองรับคอนโทรลเลอร์ Xbox อย่างเต็มรูปแบบจริง ๆ ก็ต่อเมื่อเกมสามารถทำสิ่งต่อไปนี้ได้: `,
  _ = `ผู้เล่นจะต้องสามารถทำทุกอย่างในเกมได้โดยใช้คอนโทรลเลอร์เท่านั้น ซึ่งรวมถึงสามารถใช้งานได้ก่อนการเริ่มเกม เล่นเกม โต้ตอบกับเมนู เปลี่ยนการตั้งค่า และออกจากเกมได้`,
  _ = `เมื่อคอนโทรลเลอร์ถูกตัดการเชื่อมต่อ เกมจะต้องหยุดชั่วคราว เว้นแต่จะเป็นเกมที่มีผู้เล่นหลายคนเท่านั้น`,
  _ = `หน้าต่างแจ้งให้ป้อนข้อความจะต้องเปิดคีย์บอร์ดเสมือนขึ้นมาบนหน้าจอ`,
  _ = `หากเกมของคุณรองรับเกมผู้เล่นหลายคนในเครือข่าย โหมดดังกล่าวจะต้องทำงานกับคอนโทรลเลอร์หลายตัวได้`,
  _ = `เกมของคุณมีคุณสมบัติตรงตามเกณฑ์ข้างต้นสำหรับการรองรับคอนโทรลเลอร์ Xbox อย่างเต็มรูปแบบหรือไม่?`,
  _ = `การรองรับคอนโทรลเลอร์ PlayStation`,
  _ = `หากเกมของคุณรองรับคอนโทรลเลอร์ PlayStation ตั้งแต่หนึ่งรุ่นขึ้นไปตามรายการด้านล่างนี้ โดยทั่วไปผู้เล่นควรจะสามารถใช้คอนโทรลเลอร์เหล่านั้นทำทุกอย่างในเกมได้เช่นเดียวกับที่ใช้คอนโทรลเลอร์ Xbox ทำได้นอกจากนี้ จะถือว่าเกมของคุณรองรับคอนโทรลเลอร์ PlayStation ได้ ก็ต่อเมื่อทำสิ่งต่อไปนี้ได้เท่านั้น: `,
  _ = `แสดงภาพสัญลักษณ์ (ไอคอน) ที่ถูกต้องบนหน้าจอเมื่อมีหน้าต่างแจ้งให้ผู้ใช้ทราบว่าต้องกดปุ่มที่เฉพาะเจาะจงบนคอนโทรลเลอร์`,
  _ = `เล่นเกม โต้ตอบกับเมนู เปลี่ยนการตั้งค่า และออกจากเกม`,
  _ = `<1>หมายเหตุเกี่ยวกับ USB/บลูทูธ: </1> ในกรณีของคอนโทรลเลอร์ PlayStation บน PC อาจเป็นเรื่องปกติที่การเชื่อมต่อ USB จะทำงานได้ดี แต่เมื่อเชื่อมต่อผ่านบลูทูธจะไม่มีการรองรับในระดับเดียวกัน โปรดตรวจสอบยืนยันกับทีมงานด้านเทคนิคของคุณว่าเกมใช้งานกับบลูทูธได้จริงก่อนที่จะเลือกรายการด้านล่าง`,
  _ = `<1>ใช่</1> เกมของฉันรองรับ:  (เลือกทั้งหมดที่ถูกต้อง)`,
  _ = `การผสานรวม Steam Input API`,
  _ = `หากเกมของคุณได้ผสานรวมกับ Steam Input API อย่างเต็มรูปแบบแล้ว เกมนั้นจะทำงานได้อย่างสมบูรณ์กับคอนโทรลเลอร์เกือบทุกรุ่นในบรรดา 200 กว่ารุ่นที่ผู้เล่นเชื่อมต่อ รวมไปถึงรุ่นในอนาคต เกมของคุณจะเรียกได้ว่ารองรับคอนโทรลเลอร์เหล่านี้ได้จริง ๆ ก็ต่อเมื่อต้องทำสิ่งต่อไปนี้ได้เป็นอย่างน้อย: `,
  _ = `ปรับใช้งานคำสั่ง Steam Input API และค้นหาแหล่งที่มาของคำสั่งที่เกี่ยวข้องเพื่อแสดงภาพสัญลักษณ์ในเกมของคอนโทรลเลอร์ที่ถูกต้องสำหรับรุ่นของคอนโทรลเลอร์หลัก`,
