  _ = `เนื้อหาดาวน์โหลดนี้ต้องอาศัยเนื้อหาดาวน์โหลดอีกรายการหนึ่งจึงจะใช้งานได้หรือไม่? โปรดเลือกเนื้อหาดาวน์โหลดรายการอื่นที่จำเป็นเพื่อแสดงให้เห็นว่าจำเป็นต้องมี ร้านค้าจะแสดงเนื้อหาอื่นที่จำเป็นนี้โดยอัตโนมัติ พร้อมด้วยตัวเลือกในการสั่งซื้อเนื้อหาดาวน์โหลดรายการอื่นทั้งหมดที่จำเป็นด้วย`,
  _ = `เพิ่มเป็นเนื้อหาอื่นที่จำเป็น`,
  _ = `ความสัมพันธ์ของเนื้อหาอื่นที่จำเป็น`,
  _ = `จำเป็นต้องมี`,
  _ = `ต้องอาศัยเนื้อหาดาวน์โหลดอื่นที่จำเป็นจึงจะใช้งานและได้รับประสบการณ์ที่เหมาะสมเมื่อเล่นเนื้อหาดาวน์โหลดนี้`,
  _ = `แนะนำ`,
  _ = `ขอแนะนำให้ใช้เนื้อหาดาวน์โหลดอื่นที่จำเป็นเพื่อให้เพลิดเพลินกับเนื้อหาดาวน์โหลดนี้ได้อย่างเต็มที่`,
  _ = `ภาพรวม`,
  _ = `การออกแบบ`,
  _ = `วางจำหน่าย`,
