  _ = `ซีซันพาสเป็นเนื้อหาดาวน์โหลดที่สั่งซื้อได้ พร้อมด้วยสัญญาว่าจะจัดส่งเนื้อหาในอนาคตให้แก่ลูกค้าที่สั่งซื้อ โดยอาจจะอยู่ในรูปของการเปิดตัวเป็นเนื้อหาดาวน์โหลดแยกต่างหาก หรือเนื้อหาเพิ่มเติมที่จะปลดล็อกภายในเกมหลัก`,
  _ = `เพื่อเป้าหมายนี้ ผู้พัฒนาจะต้องอธิบายเนื้อหาและวันที่จะจัดส่งเนื้อหาให้ผู้เล่นทราบ โดยการกรอกเนื้อหาและวันที่แต่ละรายการด้านล่าง`,
