  _ = `สร้างการวางจำหน่ายเนื้อหาใหม่`,
  _ = `การวางจำหน่ายเนื้อหาคือสินค้าที่ลูกค้าเข้าใจว่าจะจัดส่งให้ตนโดยเฉพาะ พร้อมทั้งวันที่ที่คาดว่าจะได้รับสินค้า`,
  _ = `สร้างการวางจำหน่ายเนื้อหาใหม่`,
  _ = `โปรดอธิบายให้ผู้เล่นทราบถึงเนื้อหาของซีซันพาสที่คุณวางจำหน่าย`,
  _ = `คำอธิบายภายใน - บอก Valve ว่าคุณตั้งใจจะรวบรวมอะไรไว้ในหลักชัยนี้`,
