  _ = `ชื่อที่ลูกค้ามองเห็น`,
  _ = `การแสดงวันที่`,
  _ = `วันวางจำหน่ายที่ตั้งใจไว้`,
  _ = `ซึ่งเป็นวันที่ที่คุณตั้งใจจะวางจำหน่ายเนื้อหานี้ให้แก่ผู้เล่น วันที่ดังกล่าวใช้เพื่อตั้งค่าการแจ้งเตือนบนกระดานรวม Steamworks ภายในของคุณ โปรดใช้เขตเวลาท้องถิ่นของคุณ`,
  _ = `วันวางจำหน่าย`,
  _ = `ลูกค้าสามารถเข้าถึงเนื้อหานี้ได้ครั้งแรกเมื่อใด`,
  _ = `ทำเครื่องหมายเป็นเผยแพร่ไปก่อนแล้ว`,
  _ = `เนื้อหานี้ออกเผยแพร่ไปก่อนหน้านี้แล้ว เมื่อทำเครื่องหมายไว้ จะอนุญาตให้ตั้งค่าวันที่ย้อนหลังได้ เมื่อเผยแพร่แล้ว จะไม่แจ้งให้ลูกค้าทราบเกี่ยวกับการเผยแพร่ หากผ่านพ้นวันที่ไปแล้ว จะไม่สามารถยกเลิกการทำเครื่องหมายได้`,
  _ = `ไม่สามารถยกเลิกการตั้งค่าเป็นเผยแพร่ไปก่อนแล้วได้ ยกเว้นว่าจะย้ายวันที่เผยแพร่ไปเป็นวันที่ในอนาคตก่อน`,
  _ = `ต้องบันทึกและเผยแพร่`,
  _ = `วันที่ต้องเป็นวันในอดีตเนื่องจากมีการเผยแพร่เนื้อหานี้ไปแล้ว`,
  _ = `อัปเดตคำนิยามของการจัดส่งเนื้อหา`,
  _ = `บันทึกสิ่งนี้ในเซิร์ฟเวอร์`,
  _ = `การวางจำหน่ายเนื้อหา`,
  _ = `ไม่ได้กำหนดการวางจำหน่ายเนื้อหา`,
