  _ = `เตรียมวางจำหน่าย`,
  _ = `ทำเครื่องหมายเป็นเผยแพร่แล้ว`,
  _ = `แก้ไขการตั้งค่าวันวางจำหน่าย`,
  _ = `ทำเครื่องหมาย %1$s เป็น "เผยแพร่แล้ว"`,
  _ = `เนื้อหานี้พร้อมให้ผู้เล่นสามารถเล่นได้หรือไม่?`,
  _ = `เนื้อหาถูกทำเครื่องหมายเป็นเผยแพร่ไปก่อนแล้ว คุณสามารถเลือกที่จะระบุได้ว่าเนื้อหานี้ได้พร้อมให้ผู้เล่นเล่นได้แล้วอย่างไร?`,
  _ = `เนื้อหานี้จัดส่งอย่างไร?`,
  _ = `เป็นอัปเดตส่วนหนึ่งของเกม - เนื้อหาใหม่รวมอยู่ในเกมหลักหรือใช้เนื้อหาดาวน์โหลดที่ซ่อนอยู่`,
  _ = `โปรดเปิดตัวบิลด์ที่อัปเดตแล้วของคุณและโพสต์ประกาศบน Steam พร้อมรายละเอียดเกี่ยวกับเนื้อหา`,
  _ = `เป็นรายการส่วนหนึ่งของเนื้อหาดาวน์โหลด - เนื้อหาใหม่ได้รับการนำเสนอโดยหน้าร้านค้าเนื้อหาดาวน์โหลดใหม่`,
  _ = `โปรดเปิดตัวเนื้อหาดาวน์โหลดและเพิ่มไอดีแอปของเนื้อหาดาวน์โหลดดังกล่าวในแพ็กเกจของซีซันพาส เพื่อให้ผู้เล่นได้รับเนื้อหานั้นโดยอัตโนมัติ`,
  _ = `เลือกประกาศเกี่ยวกับการอัปเดตที่อธิบายถึงการเปิดตัวครั้งนี้:`,
  _ = `เลือกเนื้อหาดาวน์โหลดที่มีเนื้อหานี้`,
