  _ = `เนื้อหาดาวน์โหลดที่จัดส่งแล้ว`,
  _ = `รายชื่อเนื้อหาดาวน์โหลดที่เกี่ยวข้องกับเกมหลักและมองเห็นได้ในร้านค้า แต่ไม่ใช่ซีซันพาสและไม่ได้เชื่อมโยงกับการวางจำหน่ายเนื้อหาอื่นอยู่แล้ว`,
  _ = `เชื่อมโยงกิจกรรมเปิดตัวที่มองเห็นได้`,
  _ = `ภายใต้เกมหลัก โปรดเลือกกิจกรรมที่มองเห็นได้และมีอยู่แล้ว ซึ่งอธิบายถึงการเปิดตัว กิจกรรมดังกล่าวจะมองเห็นได้จากหน้าเนื้อหาดาวน์โหลดของซีซันพาส`,
  _ = `ไม่พบเนื้อหาดาวน์โหลด - เนื้อหาดาวน์โหลดจะต้องวางจำหน่ายก่อนจึงจะสามารถทำเครื่องหมายเป็น "เสร็จสมบูรณ์" ที่นี่ได้`,
  _ = `วันวางจำหน่ายเนื้อหาตั้งแต่หนึ่งรายการขึ้นไปได้ผ่านพ้นไปแล้ว โปรดวางจำหน่ายเนื้อหานี้หรืออัปเดตวันที่ที่คาดว่าจะวางจำหน่าย`,
