  _ = `ไม่มีชื่อในภาษา %1$s จะย้อนกลับไปยังชื่อในภาษา %2$s`,
  _ = `เลือกได้: รวมถึงกิจกรรมที่อธิบายถึงการเปิดตัวเนื้อหาดาวน์โหลดด้วยหรือไม่?`,
  _ = `พร้อมเล่นแล้ว`,
  _ = `วางจำหน่ายแล้ว`,
