  _ = `แบบสำรวจเกี่ยวกับการพบปะทีมงาน Steam ในกิจกรรมระดับอุตสาหกรรม`,
  _ = `สวัสดี %1$s,%2$s คุณต้องการพบเราที่ไหน?`,
  _ = `รายชื่อด้านล่างนี้คือกิจกรรมที่สมาชิกของทีมงาน Steam พิจารณาที่จะเข้าร่วม หากคุณคิดว่าจะไปเข้าร่วม หรือหากคุณอาศัยอยู่ในบริเวณใกล้เคียงและต้องการไปเข้าร่วมเพื่อพบปะสนทนากัน โปรดแจ้งให้เราทราบในแบบฟอร์มด้านล่างนี้ เราจะใช้ข้อมูลที่คุณกรอกไว้เพื่อช่วยให้วางแผนการเดินทางและกำหนดเวลาเกี่ยวกับกิจกรรมให้ดีขึ้น หากคุณลงทะเบียนเข้าร่วมกิจกรรมที่เราตั้งใจจะเข้าร่วมด้วย เราจะให้ความสำคัญกับผู้ที่เข้าร่วมกิจกรรมเป็นอันดับแรกก่อนที่จะส่งคำเชิญของเราไปยังบุคคลทั่วไป`,
  _ = `เกี่ยวกับคุณ`,
  _ = `โปรดแจ้งให้เราทราบเกี่ยวกับคุณและวิธีที่ดีที่สุดในการติดต่อคุณ:`,
  _ = `ที่อยู่อีเมล`,
  _ = `ที่อยู่อีเมลขาดหายไป`,
  _ = `อัปเดตที่อยู่อีเมลหรือไม่?`,
  _ = `ค่าเริ่มต้นนี้จะใช้ที่อยู่อีเมลที่ลงทะเบียนไว้กับบัญชีพันธมิตรของคุณ คุณสามารถแก้ไขได้หากต้องการให้ส่งการสื่อสารเกี่ยวกับกิจกรรมไปยังที่อยู่อีเมลอื่น`,
