  _ = `คุณจะไปที่ไหน?`,
  _ = `โปรดแจ้งให้เราทราบว่าคุณพิจารณาที่จะเข้าร่วมกิจกรรมใดบ้างที่อุตสาหกรรมเกมจัดขึ้นในปี %1$s`,
  _ = `ระบุกิจกรรมที่ทีมงาน Steam วางแผนว่าจะเข้าร่วม ส่วนกิจกรรมอื่น ๆ ทั้งหมดนั้นยังอยู่ระหว่างการพิจารณา`,
