  _ = `รางวัลความสำเร็จที่คุณกำหนดไว้ก่อนหน้านี้แต่ไม่พบในไฟล์ CSV ที่นำเข้าจะแสดงไว้ที่นี่ รางวัลความสำเร็จเหล่านี้จะยังคงอยู่เว้นแต่คุณจะทำเครื่องหมายในกล่องด้านล่างเพื่อลบออก`,
  _ = `ลบรางวัลความสำเร็จเหล่านี้`,
  _ = `ต้องการแก้ไข (%1$s)`,
  _ = `รางวัลความสำเร็จที่ได้รับการแก้ไขจะแสดงอยู่ที่นี่ รายการเหล่านี้จะได้รับการอัปเดต`,
  _ = `ไม่ได้รับการแก้ไข (%1$s)`,
  _ = `รางวัลความสำเร็จที่ไม่ได้รับการแก้ไขจะแสดงอยู่ที่นี่ รายการเหล่านี้จะไม่ได้รับการอัปเดต`,
  _ = `ภาพรางวัลความสำเร็จขาดหายไป`,
  _ = `ไฟล์ csv ไม่ถูกต้อง: รางวัลความสำเร็จที่เพิ่มเข้ามาทั้งหมดต้องอ้างอิงถึงสถิติในชุดเดียว (หรือในชุดเริ่มต้น)`,
  _ = `ชื่อ API ไม่ถูกต้อง: ชื่อต้องไม่ซ้ำกัน`,
  _ = `ตรวจพบข้อผิดพลาดในไฟล์ CSV ที่นำเข้า โปรดแก้ไขข้อผิดพลาดด้านล่างแล้วอัปโหลดไฟล์อีกครั้ง`,
  _ = `ระบุการเปลี่ยนแปลง`,
  _ = `ไอดีชุด`,
  _ = `ชุดที่มีการแก้ไขชื่อจะแสดงอยู่ที่นี่ รายการเหล่านี้จะได้รับการอัปเดต`,
  _ = `ชุดที่ไม่ได้รับการแก้ไขจะแสดงอยู่ที่นี่ รายการเหล่านี้จะไม่ได้รับการอัปเดต`,
  _ = `ไอดีชุดไม่ถูกต้อง: ไอดีชุดต้องไม่ซ้ำกัน`,
  _ = `ไอดีชุดไม่ถูกต้อง: ไม่สามารถเปลี่ยนชื่อชุดรางวัลความสำเร็จหลักของเกมได้`,
  _ = `คอลัมน์ที่ไม่คาดคิด: "%1$s" ไม่ใช่ภาษาที่รองรับ`,
  _ = `ชื่อไม่ถูกต้อง: ชุดต้องมีชื่อเป็นภาษาอังกฤษ`,
