  _ = `ไอดีชุดไม่ถูกต้อง: ไอดีชุดดังกล่าวไม่มีอยู่`,
  _ = `จัดเรียงลำดับชุดใหม่`,
  _ = `ลากและวางชุดรางวัลความสำเร็จเพื่อกำหนดลำดับการแสดงผลสำหรับผู้ใช้`,
  _ = `ไม่สามารถย้ายชุดเริ่มต้นได้`,
  _ = `ตัวเลือก`,
  _ = `ความกว้างและความสูงของภาพต้องมีขนาดเท่ากัน`,
