  _ = `ไฟล์ CSV คำนิยามที่อัปโหลดไม่มีรางวัลความสำเร็จ "%1$s" ดังนั้นไอคอนนี้จะไม่ได้รับการกำหนด เพิ่มรางวัลความสำเร็จดังกล่าวไปยังไฟล์ CSV หรือลบไฟล์ CSV เพื่ออัปโหลดไอคอนแยกต่างหาก`,
